mapper.select:
select idsucursal, idempresa, sucursal, nombresucursal, municipio, telefono, direccion
from facturacion.sucursales
where concat(sucursal) ilike '%'||#{termino}||'%' and idempresa = #{idempresa}
order by sucursal
limit #{cantidad} offset #{pagina}

select count(idsucursal)
from facturacion.sucursales
where concat(sucursal) ilike '%'||#{termino}||'%' and idempresa = #{idempresa}

select idsucursal, idempresa, sucursal, nombresucursal, municipio, telefono, direccion
from facturacion.sucursales
where idsucursal=#{id}
